using Meridian.Mediator.Caching;
using Microsoft.Extensions.Caching.Distributed;

namespace Meridian.Mediator.Caching.Tests;
public sealed class DistributedCacheTests
{
    internal static DistributedCacheProvider Provider(FakeBackend b,int schema=1,ICacheValueSerializer? serializer=null) { var r=SerializationContractTests.Registry(schema); var s=serializer??new JsonCacheValueSerializer(r); return new(b,s,new CacheValueCodec(r,s),new()); }
    internal static DistributedCacheProvider ProviderForBackend(IDistributedCache b) { var r=SerializationContractTests.Registry();var s=new JsonCacheValueSerializer(r);return new(b,s,new CacheValueCodec(r,s),new()); }
    [Fact] public async Task Cache_RoundTrip_Uses_Registered_JsonTypeInfo() { var b=new FakeBackend(); await Provider(b).SetAsync("key",new Reply("actual",42),null,default); var hit=await Provider(b).GetAsync("key",default); Assert.True(hit.Found); Assert.Equal(new Reply("actual",42),hit.Value); Assert.Equal(TimeSpan.FromMinutes(5),b.Options!.AbsoluteExpirationRelativeToNow); }
    [Fact] public async Task Unknown_Contract_Is_Miss() { var b=new FakeBackend { Bytes=SerializationContractTests.Frame("remote",1,"secret") }; Assert.False((await Provider(b).GetAsync("secret-key",default)).Found); Assert.Equal(1,b.Removes); Assert.Null(b.Bytes); }
    [Fact] public async Task Schema_Mismatch_Is_Miss() { var b=new FakeBackend(); await Provider(b).SetAsync("key",new Reply("a",1),null,default); Assert.False((await Provider(b,2).GetAsync("key",default)).Found); Assert.Equal(1,b.Removes); }
    [Theory] [InlineData("get")] [InlineData("set")] [InlineData("remove")] public async Task Transport_Failure_Is_Propagated(string operation) { var e=new IOException("transport"); var b=new FakeBackend { Fault=e, FaultOperation=operation }; var p=Provider(b); var thrown=await Assert.ThrowsAsync<IOException>(()=>operation=="get" ? p.GetAsync("key",default) : operation=="set" ? p.SetAsync("key",new Reply("v",1),null,default) : p.RemoveAsync("key",default)); Assert.Same(e,thrown); }
    [Fact] public async Task Corruption_Removal_Failure_Cannot_Return_Miss() { var e=new IOException("remove"); var b=new FakeBackend { Bytes=[0],Fault=e,FaultOperation="remove" }; Assert.Same(e,await Assert.ThrowsAsync<IOException>(()=>Provider(b).GetAsync("key",default))); }
    [Fact] public async Task Null_Remote_Entry_Is_Removed_And_Nonpositive_Duration_Removes() { var b=new FakeBackend { Bytes=SerializationContractTests.Codec().Encode(null,"reply.v1") }; Assert.False((await Provider(b).GetAsync("key",default)).Found); Assert.Equal(1,b.Removes); await Provider(b).SetAsync("key",new Reply("v",1),TimeSpan.Zero,default); Assert.Equal(2,b.Removes); Assert.Equal(0,b.Sets); }
    [Fact] public async Task Serializer_Programming_Failure_Is_Not_Evicted() { var s=new SerializationContractTests.OpaqueSerializer { Failure=new InvalidOperationException("program") }; var b=new FakeBackend { Bytes=SerializationContractTests.Codec().Encode(new Reply("v",1),"reply.v1") }; Assert.Same(s.Failure,await Assert.ThrowsAsync<InvalidOperationException>(()=>Provider(b,serializer:s).GetAsync("key",default))); Assert.Equal(0,b.Removes); }
    [Fact] public async Task Cancellation_And_Remove_Cancellation_Propagate() { using var c=new CancellationTokenSource(); c.Cancel(); var b=new FakeBackend(); await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>Provider(b).GetAsync("key",c.Token)); b.Bytes=[0]; b.RemoveToken=c.Token; await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>Provider(b).GetAsync("key",default)); }
    [Fact] public async Task Corrupt_Read_Concurrent_Write_Can_Lose_A_Hit_But_Never_Return_Corruption() { var b=new FakeBackend { Bytes=[0] }; b.BeforeRemove=()=>b.Bytes=SerializationContractTests.Codec().Encode(new Reply("fresh",1),"reply.v1"); Assert.False((await Provider(b).GetAsync("key",default)).Found); Assert.Null(b.Bytes); Assert.Equal(1,b.Removes); }
    internal sealed class FakeBackend : IDistributedCache { public byte[]? Bytes {get;set;} public int Removes {get;private set;} public int Sets {get;private set;} public DistributedCacheEntryOptions? Options {get;private set;} public Exception? Fault {get;set;} public string? FaultOperation {get;set;} public CancellationToken RemoveToken {get;set;} public Action? BeforeRemove {get;set;} private void Check(string operation,CancellationToken ct) { ct.ThrowIfCancellationRequested(); if(FaultOperation==operation && Fault is not null) throw Fault; } public byte[]? Get(string key)=>Bytes; public Task<byte[]?> GetAsync(string key,CancellationToken token=default) { Check("get",token); return Task.FromResult(Bytes); } public void Set(string key,byte[] value,DistributedCacheEntryOptions options) { Bytes=value; Options=options; Sets++; } public Task SetAsync(string key,byte[] value,DistributedCacheEntryOptions options,CancellationToken token=default) { Check("set",token); Set(key,value,options); return Task.CompletedTask; } public void Remove(string key) { BeforeRemove?.Invoke(); Bytes=null; Removes++; } public Task RemoveAsync(string key,CancellationToken token=default) { Check("remove",token); RemoveToken.ThrowIfCancellationRequested(); Remove(key); return Task.CompletedTask; } public void Refresh(string key) { } public Task RefreshAsync(string key,CancellationToken token=default)=>Task.CompletedTask; }
}
